  "check_code": "import hashlib
import json
from datetime import datetime, timezone


SYSTEM = "auditboard_brand_compliance"
TARGET_TEST = "TEST-PH-EMAIL-NA"
OTHER_TESTS_DIGEST = "7300ba430b2252ce852965c9ec519c7407e0cf741c5a352ea57ace78abb63e2c"


def _target(ws):
    rows = db_query(
        ws,
        SYSTEM,
        "SELECT * FROM control_tests WHERE test_id = ?",
        (TARGET_TEST,),
    )
    return rows[0] if len(rows) == 1 else None


def _parse_timestamp(value):
    if value is None:
        return None
    text = str(value).strip()
    if text.endswith("Z"):
        text = text[:-1] + "+00:00"
    try:
        parsed = datetime.fromisoformat(text)
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def check_target_closure_state(ws):
    row = _target(ws)
    if row is None:
        return {"score": 0, "detail": "The target control test is missing or duplicated."}
    expected_time = datetime(2026, 8, 14, 12, 0, tzinfo=timezone.utc)
    actual_time = _parse_timestamp(row.get("closed_at"))
    expected = {
        "reviewer_id": "USR-MER-17",
        "result": "not_tested",
        "applicable_flag": 0,
        "valid_flag": 1,
    }
    mismatches = [key for key, value in expected.items() if row.get(key) != value]
    if actual_time != expected_time:
        mismatches.append("closed_at")
    if mismatches:
        return {"score": 0, "detail": "Incorrect target closure fields: " + ", ".join(mismatches)}
    return {"score": 1, "detail": "The target test has the required reviewer, timestamp, not-tested result, validity, and unchanged non-applicability."}


def check_evidence_specific_closure_note(ws):
    row = _target(ws)
    if row is None:
        return {"score": 0, "detail": "The target control test is missing or duplicated."}
    evidence = str(row.get("evidence_hash") or "")
    if not evidence.startswith("sha256:email-no-logo-01") or "|closure:" not in evidence:
        return {"score": 0, "detail": "The original evidence reference or appended closure rationale is missing."}
    note = norm_label(evidence.split("|closure:", 1)[1])
    has_period = "september" in note or "sep" in note
    has_email = "email" in note
    has_no_logo = "logo" in note and (
        "nologo" in note
        or "nophilipslogo" in note
        or "withoutlogo" in note
        or "logoabsent" in note
        or "logonotpresent" in note
        or "zerologo" in note
    )
    has_not_applicable = "notapplicable" in note or "inapplicable" in note or "n/a" in note
    if not all((has_period, has_email, has_no_logo, has_not_applicable)):
        return {"score": 0, "detail": "The closure rationale does not connect the September email, absent logo instance, and non-applicability."}
    return {"score": 1, "detail": "The evidence-specific closure rationale is present and preserves the original evidence reference."}


def check_target_identity_preserved(ws):
    row = _target(ws)
    if row is None:
        return {"score": 0, "detail": "The target control test is missing or duplicated."}
    expected = {
        "asset_id": "ASSET-25-09-SUM-W01",
        "control_id": "PH-LOGO-SIZE",
        "guideline_id": "GUIDE-PH-2024-07",
        "instance_count": 1,
    }
    mismatches = [key for key, value in expected.items() if row.get(key) != value]
    if mismatches:
        return {"score": 0, "detail": "Target identity fields changed: " + ", ".join(mismatches)}
    return {"score": 1, "detail": "The target test remains linked to the original asset, control, guideline, and instance count."}


def check_other_control_tests_unchanged(ws):
    rows = db_query(
        ws,
        SYSTEM,
        "SELECT * FROM control_tests WHERE test_id <> ? ORDER BY test_id",
        (TARGET_TEST,),
    )
    payload = json.dumps(rows, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()
    if len(rows) != 436 or digest != OTHER_TESTS_DIGEST:
        return {"score": 0, "detail": "One or more non-target control tests were changed, added, or removed."}
    return {"score": 1, "detail": "All non-target control tests are unchanged."}
